/* Types */
/**  Whether Muna may read the Action Center, as the panel states it. */
export type AccessState = "allowed" | 
/**  The user said no in Settings → Privacy → Notifications; the panel offers that page. */
"denied" | 
/**  Never asked; the panel offers *Allow*, which shows the consent prompt. */
"unspecified" | 
/**  This Windows has no listener at all. */
"unavailable";

/**  The connected account, as the settings pane names it. */
export type Account = {
	provider: Provider,
	login: string,
	avatarUrl: string | null,
};

/**  Long-lived strip content owned by a module (`id` is `<module>:<key>`). */
export type Activity = {
	id: string,
	module: string,
	/**  0–100; higher wins. Defaults live in [`priority`]. */
	priority: number,
	leading: Leading | null,
	trailing: Trailing | null,
	/**  Text for the wide form. A change here shows the wide form for [`WIDE_FORM_HOLD`]. */
	wide: StripMessage | null,
};

/**  An activity plus the user state the scheduler keeps for it (the expanded list). */
export type ActivityState = {
	activity: Activity,
	focused: boolean,
};

/**  Static facts about the running build, for the settings "About" section and diagnostics. */
export type AppInfo = {
	name: string,
	version: string,
	/**  `"windows"` or `"fake"`. */
	platform: string,
	profileDir: string,
};

/**  Prepared artwork as the UI consumes it. */
export type Artwork = {
	/**  Cache key ([`art_key`]); the media state refers to artwork by it. */
	key: string,
	/**  `data:image/…;base64,…`, at most [`MAX_SIDE`] px on the longest side. */
	src: string,
	/**  Three CSS colours, dominant first (`--media-accent-1..3`). */
	palette: string[],
	width: number,
	height: number,
};

/**  How the automatic location stands. */
export type AutoLocationStatus = 
/**  Asking Windows, or about to. */
"resolving" | 
/**  A position is known. */
"ready" | 
/**
 *  Windows keeps location from desktop apps; the panel says "Choose a city" and the module
 *  does not ask again until "Try again".
 */
"denied" | 
/**  The machine has no location source. */
"unavailable" | 
/**  The fix failed for another reason; retried with backoff. */
"failed";

/**
 *  The paired devices and the radio as the module now sees them (docs/modules/bluetooth.md):
 *  after a platform report, a command, or a settings change that hides or shows a device.
 */
export type BluetoothChanged = {
	snapshot: BluetoothSnapshot,
};

/**
 *  What the panel can ask for. Hiding a device is a setting (`hiddenDevices`), written through
 *  the settings editor like any other.
 */
export type BluetoothCommand = { kind: "connect"; id: string } | { kind: "disconnect"; id: string } | { kind: "setRadio"; on: boolean };

/**
 *  What a paired device is, so the UI can pick its glyph (docs/modules/bluetooth.md). Windows
 *  reports it as `System.Devices.Aep.Category`; a device without one falls back to hints in
 *  its name, then to `Other`.
 */
export type BluetoothDeviceKind = "headphones" | "speaker" | "phone" | "mouse" | "keyboard" | "controller" | "other";

export type BluetoothDeviceView = {
	id: string,
	name: string,
	connected: boolean,
	batteryPercent: number | null,
	kind: BluetoothDeviceKind,
	hidden: boolean,
};

/**  The Bluetooth radio's power state (docs/modules/bluetooth.md "Radio toggle"). */
export type BluetoothRadioState = "on" | "off" | 
/**
 *  No Bluetooth radio, or Windows will not say (a policy, or the radio is disabled in
 *  Device Manager). Paired devices may still enumerate.
 */
"unavailable";

/**  What the panel and the settings pane show. */
export type BluetoothSnapshot = {
	radio: BluetoothRadioState,
	/**
	 *  `false` when this build cannot enumerate devices at all (the watchers failed to start,
	 *  or a platform without Bluetooth); the panel then says so instead of showing an empty list.
	 */
	available: boolean,
	/**
	 *  Connected first, then by name. Hidden devices are included with `hidden: true` so the
	 *  settings pane can offer them back; the panel leaves them out.
	 */
	devices: BluetoothDeviceView[],
};

/**  How a display's backlight is driven (docs/modules/hud.md "Brightness"). */
export type BrightnessKind = 
/**  A laptop panel through WMI (`WmiMonitorBrightness`); changes arrive as events. */
"internal" | 
/**
 *  An external monitor through DDC/CI (`dxva2`); ~50 ms per call and best effort, so the
 *  HUD only offers it once the capability probe said yes.
 */
"external";

/**  A display whose brightness Muna can read and set. */
export type BrightnessMonitor = {
	/**
	 *  Stable for the session: the WMI instance name for a panel, the GDI device name plus
	 *  the physical index (`\\.\DISPLAY1#0`) for DDC/CI.
	 */
	id: string,
	/**  What the monitor calls itself (`szPhysicalMonitorDescription`), or the panel's name. */
	name: string,
	/**  0–100, normalised from the monitor's own range. */
	percent: number,
	kind: BrightnessKind,
};

/**
 *  The subscribed calendars, their events and their refresh state as the module now sees
 *  them (docs/modules/calendar.md): after a fetch, a command or a settings change.
 */
export type CalendarChanged = {
	snapshot: CalendarSnapshot,
};

/**  What the panel can ask for. Sources and options go through the settings document. */
export type CalendarCommand = 
/**  Fetches every enabled source now, whatever the schedule says. */
{ kind: "refresh" };

/**  One occurrence inside the window, as the panel, the widget and the strip see it. */
export type CalendarEvent = {
	/**  `<source id>:<uid>:<start>`; stable across refreshes for the same instance. */
	id: string,
	sourceId: string,
	/**  Empty when the feed had no summary; the UI names it. */
	title: string,
	location: string | null,
	startMs: number,
	endMs: number,
	allDay: boolean,
	/**
	 *  A meeting link or the event's URL; opened through `calendar_open`, never rendered as a
	 *  navigable link inside the webview.
	 */
	link: string | null,
	isMeeting: boolean,
};

/**  What the UI renders (docs/modules/calendar.md). */
export type CalendarSnapshot = {
	sources: SourceView[],
	/**  Every occurrence from enabled sources, chronological. */
	events: CalendarEvent[],
	windowStartMs: number,
	windowEndMs: number,
	/**  Some enabled source could not be reached on its last fetch. */
	offline: boolean,
};

/**
 *  Where the checks on a pull request's last commit stand, as GitHub's status check rollup
 *  reports them.
 */
export type ChecksState = 
/**  No checks run on this repository. */
"none" | 
/**  Running, queued or expected. */
"pending" | "success" | 
/**  A failed or errored check. */
"failure";

/**
 *  Why a poll or a *Connect* did not produce a queue. Never carries what the host said: the
 *  UI has one sentence per case. Named apart from the weather module's `FetchError` because
 *  both reach the generated bindings.
 */
export type CodeHostError = 
/**  No connection, a DNS failure or a timeout: the last queue stands with its time. */
"offline" | 
/**
 *  The host refused the token (401, or a 403 that is not the rate limit): it expired or
 *  was revoked. Polling stops until the user connects again.
 */
"unauthorized" | 
/**
 *  The host asked for a pause (403 or 429 with the rate-limit headers): the next poll
 *  waits longer.
 */
"rateLimited" | 
/**
 *  The host answered, but not with a queue (an error status, GraphQL errors without data,
 *  a shape this build does not understand).
 */
"provider";

/**
 *  The connected account, its review queue and the poll state as the module now sees them
 *  (docs/modules/code-hosting.md): after a poll, a command, a connect or a settings change.
 */
export type CodeHostingChanged = {
	snapshot: CodeHostingSnapshot,
};

/**
 *  What the panel can ask for. Settings go through the settings document like every module's;
 *  connecting and disconnecting have their own commands because they touch the vault.
 */
export type CodeHostingCommand = 
/**  Fetches now, whatever the schedule says. */
{ kind: "refresh" };

/**  What the UI renders (docs/modules/code-hosting.md). */
export type CodeHostingSnapshot = {
	/**  `false` until the user turns the module on; nothing below is populated meanwhile. */
	enabled: boolean,
	/**  The connected account; `None` shows *Connect* in the panel and the pane. */
	account: Account | null,
	/**  The last good queue, newest first, possibly from a previous launch. */
	pullRequests: PullRequest[],
	/**  When `pull_requests` was fetched, Unix milliseconds; the timestamp chip while offline. */
	fetchedAtMs: number | null,
	/**  A request is on the wire. */
	fetching: boolean,
	/**
	 *  Why the last poll failed; cleared by the next one that works. The queue, if any, stays.
	 *  `Unauthorized` also stops polling until the user connects again.
	 */
	error: CodeHostError | null,
};

/**
 *  The conditions at the place right now. Every number came out of JSON, which cannot spell
 *  `NaN`, so they export as plain `number`s ([`Finite`]).
 */
export type CurrentConditions = {
	/**  Local wall time of the reading, `YYYY-MM-DDTHH:MM`. */
	time: string,
	condition: WeatherCondition,
	isDay: boolean,
	temperatureC: number,
	apparentTemperatureC: number,
	humidityPercent: number,
	windKmh: number,
	pressureHpa: number,
	/**  The UV index of the current hour; `None` when the provider has none. */
	uvIndex: number | null,
};

/**  One day of the row. */
export type DayForecast = {
	/**  Local date, `YYYY-MM-DD`. */
	date: string,
	condition: WeatherCondition,
	highC: number,
	lowC: number,
	/**  Local wall time, `YYYY-MM-DDTHH:MM`. */
	sunrise: string,
	sunset: string,
	/**  The day's highest hourly chance, 0–100. */
	precipitationPercent: number | null,
};

/**  What a drag out of the notch carries (docs/modules/shelf.md "Drag out"). */
export type DragOutRequest = 
/**  Files or folders by path (the S2 spike; the product UI never holds paths). */
{ kind: "files"; paths: string[] } | 
/**  A text snippet. */
{ kind: "text"; text: string } | 
/**  Shelf items by id; Rust resolves them to their files or text. */
{ kind: "shelf"; ids: string[] };

/**  How a drag out of Muna ended ([`crate::DragSource::start_drag`]). */
export type DragOutcome = 
/**  The button was released over a target that accepted the payload. */
{ kind: "dropped"; effect: DropEffect } | 
/**  Esc, a release over nothing, or a target that refused. */
{ kind: "cancelled" };

/**
 *  S2 spike only (`MUNA_SPIKE=drag`, docs/spikes/m4-drag.md): the files the UI arms a drag-out
 *  of from the strip. The product shell answers `null`.
 */
export type DragSpike = {
	paths: string[],
};

/**  What the tile the items landed on asks for (docs/modules/drop-actions.md "Tiles"). */
export type DropAction = 
/**  The Windows share sheet (Nearby sharing, apps) with every item. */
{ kind: "share" } | 
/**  Copy or move into a configured folder. */
{ kind: "folder"; id: string } | 
/**  Pick a folder, then copy there. `title` is the picker's caption. */
{ kind: "copyTo"; title: string } | 
/**  Pick a folder, then move there. */
{ kind: "moveTo"; title: string } | 
/**  The system *Open with* dialog for the first item. */
{ kind: "openWith" } | 
/**  One archive beside the first item. */
{ kind: "zip" } | 
/**  Every dropped archive into a folder beside it. */
{ kind: "unzip" } | 
/**  Explorer with the items selected. */
{ kind: "reveal" } | 
/**  The Recycle Bin — no confirmation: Explorer's Undo brings the items back. */
{ kind: "trash" } | 
/**  Safely remove the drive the first item is on. */
{ kind: "eject" } | 
/**  Park every item on the Shelf (docs/modules/shelf.md). */
{ kind: "shelf" };

/**
 *  What a drop action does with the items, as a fact for the UI to phrase and tint
 *  (docs/modules/drop-actions.md "Tiles"). Closed on purpose, like [`Glyph`].
 */
export type DropActionKind = "share" | "copy" | "move" | "open" | "openWith" | "zip" | "unzip" | "reveal" | "trash" | "eject" | 
/**  Parked on the Shelf (docs/modules/shelf.md). */
"shelf";

/**  The drop-actions row or a job changed (docs/modules/drop-actions.md). */
export type DropActionsChanged = {
	snapshot: DropActionsSnapshot,
};

export type DropActionsSettings = {
	/**  The row, in order. A folder tile refers to an entry in `folders`. */
	tiles?: DropTile[],
	folders?: DropFolder[],
	/**  Lets a row hold [`TILES_PER_ROW_EXPANDED`] tiles instead of [`TILES_PER_ROW`]. */
	expandNotch?: boolean,
};

/**  Everything the UI needs: the row and the recent jobs. */
export type DropActionsSnapshot = {
	settings: DropActionsSettings,
	jobs: DropJob[],
};

/**  What the drop target did with a drag out of Muna. */
export type DropEffect = "copy" | "move" | "link";

/**
 *  Files entered the notch window `label` in an OLE drag: the UI morphs into the tile row.
 *  `session` names the drag until [`Dropped`] or [`DropLeft`].
 */
export type DropEntered = {
	label: string,
	session: number,
	items: DropItem[],
	position: DropPoint,
};

/**  Why a job did not finish; the UI phrases each (docs/07 UX copy: say what to do). */
export type DropFailure = 
/**  The user closed a system dialog; no notice is shown. */
"cancelled" | 
/**  An item, the folder or the removable drive is gone. */
"notFound" | 
/**  The platform cannot do this (no share sheet, no removable volume). */
"unsupported" | 
/**  *Unzip* found no zip archive among the items. */
"noArchive" | 
/**  Anything else; the reason is in the log. */
"failed";

/**  A folder tile: copy or move the dropped items into `path` (a cloud folder, a project…). */
export type DropFolder = {
	/**  Stable id the tile order refers to. */
	id: string,
	/**  The tile's title; defaults to the folder's name when empty. */
	name: string,
	path: string,
	mode: TransferMode,
};

/**
 *  One dragged item as the UI may know it (docs/modules/drop-actions.md): its name and kind,
 *  never its path.
 */
export type DropItem = {
	name: string,
	/**  Lower-case extension without the dot, when there is one. */
	extension: string | null,
	isDirectory: boolean,
};

/**  One action on one drop, as the UI sees it. */
export type DropJob = {
	id: number,
	action: DropActionKind,
	/**  How many items the action works on. */
	count: number,
	state: DropJobState,
};

export type DropJobState = 
/**  `percent` is known for zip and unzip only; the shell's own dialogs cover the rest. */
{ kind: "running"; percent: number | null } | { kind: "done" } | { kind: "failed"; reason: DropFailure };

/**  The drag left the window without dropping; the session is gone. */
export type DropLeft = {
	label: string,
	session: number,
};

/**  The drag moved over the window; at most one per frame. */
export type DropMoved = {
	label: string,
	session: number,
	position: DropPoint,
};

/**
 *  A point in whole CSS pixels relative to the notch window's client area (the units the UI
 *  lays its tiles out in).
 */
export type DropPoint = {
	x: number,
	y: number,
};

/**
 *  One tile in the row, in display order (docs/modules/drop-actions.md "Tiles"). *Convert*
 *  and *Music* arrive with their modules.
 */
export type DropTile = { kind: "nearbyShare" } | 
/**  Park the items on the Shelf (docs/modules/shelf.md). */
{ kind: "shelf" } | { kind: "folder"; id: string } | { kind: "copyTo" } | { kind: "moveTo" } | { kind: "openWith" } | { kind: "zip" } | { kind: "unzip" } | { kind: "reveal" } | { kind: "trash" } | { kind: "eject" } | 
/**  A layout helper: a hairline gap between two groups of tiles. */
{ kind: "divider" };

/**
 *  The items were released over the window at `position`. The UI resolves the tile under it
 *  and calls `drop_run`, or `drop_cancel` when nothing was hit.
 */
export type Dropped = {
	label: string,
	session: number,
	position: DropPoint,
};

/**
 *  Why a refresh did not produce a feed. Never carries what the server said: the UI has one
 *  sentence per case.
 */
export type FeedError = 
/**  No connection, a DNS failure or a timeout: the cached events stand with their time. */
"offline" | 
/**  The server refused (401, 403, 404, 410): the link expired or was revoked. */
"refused" | 
/**
 *  The server answered with something that is not a calendar (a login page, an error
 *  status, an oversized body).
 */
"invalid" | 
/**
 *  The address is not in this device's vault (the settings came from another machine, or
 *  the vault entry was removed); the source must be added again.
 */
"missingLink";

/**
 *  Why a refresh or a search did not produce a result. Never carries what the provider said:
 *  the UI has two sentences, one per case.
 */
export type FetchError = 
/**  No connection, a DNS failure or a timeout: the last forecast stands with its time. */
"offline" | 
/**
 *  The service answered, but not with a forecast (an error status or a shape this build
 *  does not understand).
 */
"provider";

/**  A whole forecast for one place. */
export type Forecast = {
	/**  IANA zone the times are in, e.g. `Europe/Berlin`. */
	timezone: string,
	current: CurrentConditions,
	/**  From the current hour on, at most [`HOURS_KEPT`] entries. */
	hourly: HourForecast[],
	/**  From today on, at most [`DAYS_KEPT`] entries. */
	daily: DayForecast[],
};

export type GeneralSettings = {
	launchAtLogin: boolean,
	reducedMotion: ReducedMotion,
	/**  Accent name from docs/05-design-system.md (`blue`, `purple`, …). */
	accent: string,
	/**  The welcome tour was finished or skipped; the settings window shows it until then (v4). */
	onboarded: boolean,
};

/**
 *  A glyph the strip can draw; the UI maps each to its icon. Closed on purpose so the
 *  mapping is exhaustive — add a variant here when a module needs a new one.
 */
export type Glyph = "battery" | "batteryCharging" | "bluetooth" | "headphones" | "lock" | "unlock" | "timer" | "bell" | "music" | "moon" | "play" | 
/**  Speaker with no waves (level 0). */
"volume" | 
/**  Speaker with one wave (1–33). */
"volumeLow" | 
/**  Speaker with two waves (34–66). */
"volumeMedium" | 
/**  Speaker with three waves (67–100). */
"volumeHigh" | 
/**  Speaker with a slash. */
"volumeMuted" | "sun" | "mic" | "micMuted" | 
/**  A task (docs/modules/todo.md): a circle with a check. */
"checkCircle" | 
/**  A processor (docs/modules/system-monitor.md): the CPU strip gauge. */
"cpu" | 
/**  An hourglass (docs/modules/day-progress.md): the working day's progress bar. */
"hourglass" | 
/**  A calendar page (docs/modules/calendar.md): the next event, tinted like its source. */
"calendar" | 
/**  A folder (docs/modules/drop-actions.md): copying or moving dropped files. */
"folder" | 
/**  A zip archive (docs/modules/drop-actions.md): zipping or unzipping. */
"archive" | 
/**  A share arrow (docs/modules/drop-actions.md): the Nearby Share sheet. */
"share" | 
/**  A bin (docs/modules/drop-actions.md): sent to the Recycle Bin. */
"trash" | 
/**  A drive (docs/modules/drop-actions.md): a removable volume ejected. */
"drive" | 
/**  A tray (docs/modules/shelf.md): items parked on the Shelf. */
"shelf" | 
/**  A pull request (docs/modules/code-hosting.md): a review was requested. */
"pullRequest" | 
/**  A circle with a cross (docs/modules/code-hosting.md): checks failed on a pull request. */
"xCircle";

/**  One action's binding as the pane and the palette see it. */
export type HotkeyBinding = {
	action: string,
	chord: string | null,
	state: HotkeyState,
};

/**
 *  A global hotkey was pressed. `action` is the id the chord is bound to (`shell.togglePanel`,
 *  `todo.quickAdd`, …; the UI resolves it against the shell's actions and the module registry)
 *  and `label` the notch on the monitor under the cursor, which is the one to act. Replaces
 *  `ShellToggleRequested` (M1), whose only action is now `shell.togglePanel`.
 */
export type HotkeyPressed = {
	action: string,
	label: string,
};

/**  What the pane shows beside each binding. */
export type HotkeyState = 
/**  Bound and registered with the OS. */
"registered" | 
/**  Bound in the settings, refused by the OS — another app holds the chord. */
"inUse" | 
/**  Bound in the settings to a chord the plugin cannot parse. */
"invalid" | 
/**  No chord. */
"unbound";

/**  One hour of the strip. */
export type HourForecast = {
	/**  Local wall time, `YYYY-MM-DDTHH:MM`. */
	time: string,
	condition: WeatherCondition,
	isDay: boolean,
	temperatureC: number,
	/**  0–100; `None` beyond the provider's horizon. */
	precipitationPercent: number | null,
};

/**  Everything the HUD UI renders and the settings pane reads. */
export type HudState = {
	/**  `None` until the platform reported a level (no render device, or not yet probed). */
	volume: VolumeLevel | null,
	/**  `None` when there is no default microphone. */
	micMuted: boolean | null,
	/**
	 *  Monitors whose brightness can be read and set, in the platform's order. A monitor
	 *  without DDC/CI never appears here (docs/modules/hud.md, acceptance criteria).
	 */
	monitors: BrightnessMonitor[],
	/**  Whether the Windows flyout is currently hidden. */
	osd: OsdState,
};

/**
 *  The HUD module's state changed: a level, the microphone, the monitor list or whether the
 *  Windows flyout is hidden (docs/modules/hud.md). The notice itself travels through
 *  [`StripContentChanged`].
 */
export type HudStateChanged = {
	state: HudState,
};

/**  Error shape every command returns. Messages are safe to show and to log (no user data). */
export type IpcError = {
	/**  Stable machine-readable code (`settings.io`, `store.sqlite`, `platform.unsupported`). */
	code: string,
	message: string,
};

/**
 *  Export-only mirror of `serde_json::Value` for the generated TypeScript (`JsonValue`).
 * 
 *  specta-typescript refuses `serde_json`'s 64-bit integer variants, so [`Settings::modules`]
 *  declares this shape for TypeScript while the runtime keeps `serde_json::Value`.
 */
export type JsonValue = null | boolean | number | null | string | JsonValue[] | { [key in string]: JsonValue };

/**  The leading (left) slot of the strip. */
export type Leading = { kind: "icon"; glyph: Glyph; tint: Tint | null } | 
/**
 *  A battery glyph filled to `percent`, with a bolt while charging; the UI colours it by
 *  level (green charging, orange ≤ 20, red ≤ 10).
 */
{ kind: "battery"; percent: number; charging: boolean } | 
/**
 *  Album art or an app icon, as a data URL or asset URL. Rounded 6 px at 20 px. `glow` is
 *  a CSS colour from the artwork palette for the tinted halo behind it (docs/modules/
 *  media.md, strip form); `None` draws no halo (no palette yet, or adaptive colours off).
 */
{ kind: "image"; src: string; glow?: string | null };

/**  Where the forecast is for, as the panel shows it. */
export type LocationView = { kind: "auto"; status: AutoLocationStatus } | { kind: "manual"; place: Place };

/**  The artwork for the active media session arrived or no longer applies. */
export type MediaArtChanged = {
	art: Artwork | null,
};

export type MediaCommand = { kind: "play" } | { kind: "pause" } | { kind: "togglePlayPause" } | { kind: "next" } | { kind: "previous" } | { kind: "setShuffle"; enabled: boolean } | { kind: "setRepeat"; mode: RepeatMode } | 
/**
 *  `TryChangePlaybackPositionAsync`; refused by the implementation when the session does
 *  not advertise seeking.
 */
{ kind: "seek"; positionMs: number };

/**
 *  Which transport operations the session's app currently accepts
 *  (`GlobalSystemMediaTransportControlsSessionPlaybackControls`). The UI hides or disables a
 *  control the app refuses instead of faking it (docs/modules/media.md, "no fake seek").
 */
export type MediaControls = {
	play: boolean,
	pause: boolean,
	next: boolean,
	previous: boolean,
	seek: boolean,
	shuffle: boolean,
	repeat: boolean,
};

/**  A System Media Transport Controls session, normalised. */
export type MediaSession = {
	/**  Source `AppUserModelId` (e.g. `Spotify.exe`). */
	sourceAppId: string,
	title: string,
	artist: string,
	album: string | null,
	status: PlaybackStatus,
	/**
	 *  Position as of this snapshot. The implementation advances the app's last reported
	 *  position by its age while `Playing`, so consumers interpolate from the moment the
	 *  snapshot arrives (docs/04-windows-platform-apis.md, "Timeline").
	 */
	positionMs: number | null,
	durationMs: number | null,
	/**  `None` when the app does not report shuffle. */
	shuffle: boolean | null,
	/**  `None` when the app does not report a repeat mode. */
	repeat: RepeatMode | null,
	controls: MediaControls,
	/**  `true` for the session the OS itself calls current (`GetCurrentSession`). */
	isCurrent: boolean,
	/**
	 *  Increments each time the session's artwork bytes change; `0` while it has none. Lets a
	 *  consumer fetch [`crate::Media::thumbnail`] only when something new arrived (Spotify
	 *  delivers art 300–1000 ms after the track change).
	 */
	artVersion: number,
};

/**
 *  What `get_media_snapshot` returns: the state plus the pixels, so a window that just opened
 *  needs one round trip.
 */
export type MediaSnapshot = {
	state: MediaState,
	art: Artwork | null,
};

/**  What the UI needs besides pixels; `MediaStateChanged` carries it on every change. */
export type MediaState = {
	/**  The session the module shows, after scoring and pinning. */
	active: MediaSession | null,
	/**  Every session the OS reports, for the app picker. */
	sessions: MediaSession[],
	/**  `source_app_id` the user pinned; `None` follows the scoring. */
	pinned: string | null,
	/**  Key of the artwork that applies to `active` (`MediaArtChanged` carries the pixels). */
	artKey: string | null,
};

/**
 *  The media module's state changed: sessions, the active one, the pin or which artwork
 *  applies (docs/modules/media.md). Pixels travel separately in [`MediaArtChanged`].
 */
export type MediaStateChanged = {
	state: MediaState,
};

/**  One attached display, as reported by `EnumDisplayMonitors` / `GetDpiForMonitor`. */
export type MonitorInfo = {
	/**  Stable per-session id (device name on Windows, e.g. `\\.\DISPLAY1`). */
	id: string,
	bounds: Rect,
	workArea: Rect,
	/**  Effective DPI; 96 = 100 %. */
	dpi: number,
	isPrimary: boolean,
};

/**  Everything the shell needs for one monitor. */
export type MonitorLayout = {
	/**
	 *  `false` removes the notch from this monitor: its window is parked off-screen and the
	 *  UI pauses, so re-enabling is instant.
	 */
	enabled: boolean,
	mode: PlacementMode,
	shape: NotchShape,
	/**  Horizontal offset from the monitor centre, CSS px (positive = right). */
	offsetX: number,
	/**  Vertical offset from the top edge, CSS px. Island adds its own 6–8 px on top. */
	offsetY: number,
	stripHeight: StripHeight,
};

/**
 *  Frame statistics the UI measured during one strip ↔ panel morph. Integers only: specta
 *  exports floats as `number | null`.
 */
export type MorphReport = {
	expanded: boolean,
	frames: number,
	durationUs: number,
	maxFrameUs: number,
	/**  Frames whose delta exceeded 1.5 × 16.7 ms. */
	droppedFrames: number,
};

/**  Asks every notch window to morph (spike shortcut `Ctrl+Alt+M` or scripted run). */
export type MorphRequested = {
	expanded: boolean,
};

/**
 *  Notch (flush with the top edge, flared) or Island (floating capsule); see
 *  docs/05-design-system.md "Shape".
 */
export type NotchShape = "notch" | "island";

/**  Short, self-dismissing strip content. Pre-empts activities while held. */
export type Notice = {
	id: string,
	module: string,
	priority: number,
	leading: Leading | null,
	trailing: Trailing | null,
	wide: StripMessage | null,
	/**  How long the notice holds the strip; `0` means [`NOTICE_HOLD`]. */
	holdMs: number,
};

/**  How changes to the Action Center reach the module (ADR-0003 and its M0-E3 amendment). */
export type NotificationDelivery = 
/**
 *  `NotificationChanged` is subscribed: [`crate::PlatformEvent::NotificationsChanged`]
 *  arrives within milliseconds. Needs package identity.
 */
"push" | 
/**
 *  The subscription is not available in this process (`0x80070490` without identity); the
 *  module asks for the list once a second instead.
 */
"polling";

export type NotificationGroup = {
	appId: string,
	appName: string,
	/**  The sender's logo as a data URL; `None` when Windows has none for it. */
	logo: string | null,
	muted: boolean,
	/**  Newest first. */
	notifications: NotificationView[],
};

export type NotificationView = {
	id: number,
	appId: string,
	title: string,
	body: string,
	createdAtMs: number,
	unread: boolean,
};

/**
 *  The Action Center as the module now sees it (docs/modules/notifications.md): after a
 *  listener change, a poll that found a difference, a command, a focus change or a settings
 *  change that mutes or unmutes a sender.
 */
export type NotificationsChanged = {
	snapshot: NotificationsSnapshot,
};

/**
 *  What the panel can ask for. Muting a sender is a setting (`mutedApps`), written through the
 *  settings editor like any other.
 */
export type NotificationsCommand = 
/**  Shows the consent prompt (or, once answered, re-reads the answer). */
{ kind: "requestAccess" } | 
/**  Re-reads the Action Center now. */
{ kind: "refresh" } | 
/**  Everything listed counts as read (the panel expanded). */
{ kind: "markRead" } | 
/**  Removes one notification from the Action Center too. */
{ kind: "dismiss"; id: number } | 
/**  Removes every notification of one sender from the Action Center too. */
{ kind: "dismissApp"; appId: string } | 
/**  Empties the Action Center. */
{ kind: "clear" } | 
/**
 *  Brings the sender to the front and removes the notification, as Windows does when a
 *  toast is activated.
 */
{ kind: "open"; id: number };

/**  The Windows Settings pages [`notifications_open_settings`] can open. */
export type NotificationsSettingsPage = "privacy" | "focus";

/**  What the panel and the settings pane show. */
export type NotificationsSnapshot = {
	access: AccessState,
	/**
	 *  How changes arrive once access is allowed: `Push` with package identity, `Polling`
	 *  without; `None` until the first watch (or while access is not allowed).
	 */
	delivery: NotificationDelivery | null,
	/**  A Windows focus session is on (`None` before Windows 11 22H2). */
	focusActive: boolean | null,
	/**  Unread notifications from unmuted senders. */
	unread: number,
	/**  Newest sender first (by its latest notification). */
	groups: NotificationGroup[],
};

/**
 *  Whether the shell's own volume/brightness flyout is showing or hidden by Muna
 *  (docs/modules/hud.md "Suppress native flyout").
 */
export type OsdState = 
/**  Windows draws its flyout as usual. */
"native" | 
/**  Muna hid the flyout's content window; the watchdog restores it if Muna dies. */
"suppressed" | 
/**
 *  No flyout window exists on this build or it failed the ownership checks; nothing is
 *  suppressed and nothing breaks.
 */
"unavailable";

/**
 *  A place the user can pick (docs/modules/weather.md "manual city"), as the geocoder
 *  describes it. The coordinates came out of JSON, so they are finite.
 */
export type Place = {
	name: string,
	/**  The first administrative level (a state, a land, a prefecture), when known. */
	region: string | null,
	country: string | null,
	latitude: number,
	longitude: number,
};

/**
 *  Overlay draws over other windows and yields; Reserved registers an `AppBar` of strip height
 *  so maximised windows start below the strip (ADR-0002 consequences).
 */
export type PlacementMode = "overlay" | "reserved";

export type PlaybackStatus = "playing" | "paused" | "stopped";

/**  What the panel and the strip's hover controls can ask for. */
export type PomodoroCommand = 
/**
 *  Starts the given phase from the top, or the current one when `phase` is `None`. A
 *  running timer restarts.
 */
{ kind: "start"; phase: PomodoroPhase | null } | 
/**  Picks a preset while idle without starting it; ignored while running or paused. */
{ kind: "select"; phase: PomodoroPhase } | { kind: "pause" } | { kind: "resume" } | 
/**  Back to the top of the current phase, idle. */
{ kind: "reset" } | 
/**  Ends the current phase and moves to the next one. */
{ kind: "skip" };

/**  A phase that ran out. */
export type PomodoroFinished = {
	phase: PomodoroPhase,
	/**  The deadline passed while the machine slept or the process was suspended. */
	whileAsleep: boolean,
};

/**  One step of the pomodoro cycle; the UI localises the label and picks the tint. */
export type PomodoroPhase = "work" | "shortBreak" | "longBreak";

/**
 *  What the UI renders (docs/modules/pomodoro.md). `remaining_ms` is exact at the moment the
 *  state was produced; the UI counts down from it while `status` is `running`.
 */
export type PomodoroState = {
	phase: PomodoroPhase,
	status: PomodoroStatus,
	remainingMs: number,
	totalMs: number,
	/**  Work phases completed since the last long break. */
	completedInCycle: number,
	/**  Work phases per cycle (`settings.modules.pomodoro.longBreakEvery`). */
	cycleLength: number,
	/**  Completed work phases that ended today, local time. */
	sessionsToday: number,
	/**  The phase that ran out most recently; cleared by the next command. */
	lastFinished: PomodoroFinished | null,
};

/**
 *  The pomodoro timer changed: started, paused, ran out, or a settings change resized an idle
 *  phase (docs/modules/pomodoro.md). The strip content travels through
 *  [`StripContentChanged`].
 */
export type PomodoroStateChanged = {
	state: PomodoroState,
};

export type PomodoroStatus = 
/**  Nothing running; the ring is full and the button says start. */
"idle" | "running" | "paused";

/**
 *  A code host this build talks to. Closed on purpose, like the strip glyphs: the UI maps
 *  each to a chip and a logo.
 */
export type Provider = "gitHub";

/**
 *  One row of the queue (docs/modules/code-hosting.md "Reference"). The title, the author and
 *  the repository name are content and are never logged.
 */
export type PullRequest = {
	/**  The host's node id; stable for the life of the pull request. */
	id: string,
	provider: Provider,
	/**  `owner/name`. */
	repo: string,
	number: number,
	title: string,
	/**  The web page; the only thing `code_hosting_open` hands to the browser. */
	url: string,
	author: string,
	authorAvatarUrl: string | null,
	draft: boolean,
	additions: number,
	deletions: number,
	changedFiles: number,
	checks: ChecksState,
	reviewDecision: ReviewDecision,
	/**  The last update the host saw, Unix milliseconds; the list is newest first. */
	updatedAtMs: number,
	/**  The user's review was asked for. */
	reviewRequested: boolean,
	/**  The user opened it. */
	mine: boolean,
};

/**  Integer rectangle in physical (device) pixels, screen coordinates. */
export type Rect = {
	x: number,
	y: number,
	width: number,
	height: number,
};

export type ReducedMotion = 
/**  Follow the Windows "animation effects" setting (default). */
"system" | "on" | "off";

/**  `MediaPlaybackAutoRepeatMode`. */
export type RepeatMode = "none" | "track" | "list";

/**  The review decision on a pull request, as GitHub computes it from the required reviews. */
export type ReviewDecision = 
/**  The repository requires no review, or nobody has reviewed yet. */
"none" | "reviewRequired" | "approved" | "changesRequested";

export type Settings = {
	version: number,
	general: GeneralSettings,
	/**  Notch placement per monitor and the global shell switches (v2). */
	shell: ShellSettings,
	/**  Per-module settings keyed by module id; each module validates its own namespace. */
	modules: { [key in string]: JsonValue },
};

export type SettingsChanged = {
	settings: Settings,
};

/**
 *  A painted shape in whole CSS pixels relative to the window's client area (the UI rounds
 *  `DOMRect`s). Rust converts it to physical screen pixels for hit-testing
 *  (docs/modules/notch-shell.md).
 */
export type ShapeRect = {
	x: number,
	y: number,
	width: number,
	height: number,
};

/**  The Shelf's items or settings changed (docs/modules/shelf.md). */
export type ShelfChanged = {
	snapshot: ShelfSnapshot,
};

/**  What the panel asks for. */
export type ShelfCommand = 
/**  Park a text snippet (a paste into the panel). */
{ kind: "addText"; text: string } | { kind: "remove"; ids: string[] } | 
/**  Remove every item whose file is gone. */
{ kind: "removeMissing" } | { kind: "clear" } | 
/**  Open a file with its default handler. */
{ kind: "open"; id: string } | 
/**  Explorer with the files selected. */
{ kind: "reveal"; ids: string[] } | 
/**  The items on the clipboard: files as `CF_HDROP`, a lone snippet as text. */
{ kind: "copy"; ids: string[] };

/**  One item as the panel sees it. */
export type ShelfItem = {
	id: string,
	kind: ShelfItemKind,
	/**  The file name, or the first line of the snippet. */
	name: string,
	/**  Lower-case file extension without the dot, for the placeholder tile. */
	extension: string | null,
	/**  Bytes, when known. */
	size: number | null,
	/**  `true` for a folder. */
	isFolder: boolean,
	/**  The file is a copy in Shelf storage. */
	copied: boolean,
	/**  The referenced file is gone (docs/modules/shelf.md "broken-link state"). */
	missing: boolean,
	/**  Snippets only: the text, cut to [`PREVIEW_CHARS`]. */
	preview: string | null,
	addedAtMs: number,
};

/**  What an item is. */
export type ShelfItemKind = 
/**  A file or folder, by reference or as a copy in Shelf storage. */
"file" | 
/**  A text snippet (a URL, a paragraph). */
"text";

export type ShelfSettings = {
	/**
	 *  Copy dropped files into `%LOCALAPPDATA%\Muna\shelf` instead of referencing them, so
	 *  the item survives the original being moved or deleted.
	 */
	copyIntoStorage?: boolean,
	/**  Remove items this many days after they arrived; `0` keeps them until removed. */
	expiryDays?: number,
};

/**  Everything the panel shows. */
export type ShelfSnapshot = {
	items: ShelfItem[],
	settings: ShelfSettings,
};

/**
 *  What the UI needs to render one notch window (`ShellLayoutChanged`, `get_shell_layout`).
 *  CSS px throughout; the window itself is always [`layout::WINDOW_LOGICAL`].
 */
export type ShellLayout = {
	label: string,
	monitorId: string,
	isPrimary: boolean,
	enabled: boolean,
	mode: PlacementMode,
	shape: NotchShape,
	/**  Strip height preset in CSS px (32 / 26 / 38). */
	stripHeight: number,
	/**  CSS px between the window's top edge and the strip (0 for Notch, 8 for Island). */
	stripTopOffset: number,
	/**  `min(1000, monitorWidth − 80)`. */
	panelMaxWidth: number,
	/**  Monitor scale as a whole percentage (100, 125, 150, …). */
	scalePercent: number,
	yieldState: YieldState,
};

/**
 *  A notch window's layout changed (attached, monitor or settings changed). Emitted to every
 *  window; the payload names the window it is about.
 */
export type ShellLayoutChanged = {
	layout: ShellLayout,
};

/**  Which UI the notch window should render. */
export type ShellMode = 
/**  The product shell. */
"normal" | 
/**  The M0-E2 window spike (`MUNA_SPIKE=window`, docs/spikes/m0-window.md). */
"spikeWindow";

/**
 *  A mouse button went down while the cursor was outside every shape the notch `label`
 *  published. The window is click-through there, so the UI cannot observe that press itself;
 *  the cursor poll reports it and the UI closes an unpinned panel (S4 in docs/09-testing-qa.md).
 */
export type ShellPointerDownOutside = {
	label: string,
};

/**  Global shell settings plus the per-monitor table. */
export type ShellSettings = {
	/**  `WDA_EXCLUDEFROMCAPTURE` on every notch window. */
	hideFromCaptures: boolean,
	/**  Layout used for monitors without an entry in `monitors`. */
	defaults: MonitorLayout,
	/**  Per-monitor overrides keyed by the stable monitor id (`\\.\DISPLAY1`, …). */
	monitors: { [key in string]: MonitorLayout },
	/**
	 *  Module bar order (v3): module ids the user arranged. Ids the build does not know are
	 *  kept (the module may come back) and modules missing here follow in registry order.
	 */
	moduleOrder: string[],
	/**  Modules the user switched off (v3): hidden from the bar, backend still registered. */
	disabledModules: string[],
};

/**  The yield rules changed their mind about one notch window (docs/modules/notch-shell.md). */
export type ShellYieldChanged = {
	label: string,
	state: YieldState,
};

/**
 *  The tracked drag ended (button released). `label` is the notch window the cursor was over
 *  at that moment, if any: the UI resolves the tile under its last position and calls
 *  `snap_apply`, or `snap_cancel` when nothing was hit.
 */
export type SnapDragEnded = {
	session: number,
	label: string | null,
};

/**  The tracked drag left the notch window `label`; the zones collapse. */
export type SnapDragLeft = {
	label: string,
	session: number,
};

/**
 *  A tracked window drag (docs/modules/window-snap.md) is over the notch window `label` at
 *  `position`: the UI shows the zones once the cursor is in the hot zone and highlights the
 *  tile under it. Only on change, at most once per cursor sample.
 */
export type SnapDragMoved = {
	label: string,
	session: number,
	position: DropPoint,
};

/**  A built-in layout, in the strip's order. */
export type SnapZone = "topLeft" | "bottomLeft" | "leftHalf" | "maximize" | "rightHalf" | "topRight" | "bottomRight" | "leftThird" | "centerThird" | "rightThird";

/**  What the UI names at release: a built-in layout or one cell of the custom grid. */
export type SnapZoneRef = ({ builtIn: SnapZone }) & { cell?: never } | ({ cell: {
	row: number,
	col: number,
} }) & { builtIn?: never };

/**  One subscribed calendar, as the settings document and the UI see it. */
export type SourceSetting = {
	/**  Stable, opaque; also names the secret and the cache entry. */
	id: string,
	name: string,
	color: Tint,
	/**  A disabled source keeps its address and cache but is neither fetched nor shown. */
	enabled: boolean,
	/**  The feed's host, so the settings pane can say where it comes from without the address. */
	host: string,
};

/**  Where a source stands. */
export type SourceStatus = 
/**  Not fetched yet this launch (the cache, if any, is showing). */
{ kind: "idle" } | 
/**  A request is on the wire. */
{ kind: "fetching" } | 
/**  The last fetch worked. */
{ kind: "ok" } | 
/**  The last fetch failed; the cached events, if any, stay. `MissingLink` is not retried. */
{ kind: "error"; error: FeedError };

/**  A source as the UI shows it: the setting plus the fetch state. */
export type SourceView = {
	id: string,
	name: string,
	color: Tint,
	enabled: boolean,
	host: string,
	status: SourceStatus,
	/**  When the showing events were fetched, Unix milliseconds. */
	fetchedAtMs: number | null,
	/**  Occurrences inside the window. */
	eventCount: number,
};

/**  What the closed strip renders right now. */
export type StripContent = 
/**  Nothing to show: the strip is the bare black shape. */
{ kind: "idle" } | 
/**  An activity; `wide` says whether its text is showing (the 2.5 s burst after a change). */
{ kind: "activity"; activity: Activity; wide: boolean } | 
/**  A held notice; its text, when present, always shows. */
{ kind: "notice"; notice: Notice };

export type StripContentChanged = {
	content: StripContent,
};

/**  Strip height presets: 32 (Default) · 26 (Compact) · 38 (Comfortable) CSS px. */
export type StripHeight = "compact" | "default" | "comfortable";

/**
 *  One line of text for the wide form. Built-in notices carry their *facts* rather than a
 *  sentence so the UI can localise them; `Text` is for content that is already words
 *  (a track title, a user label) and is never logged. Glyph-only notices (charging, lock)
 *  have no message: the UI describes them from their slots for assistive technology.
 */
export type StripMessage = { kind: "text"; value: string } | { kind: "batteryLow"; percent: number } | { kind: "bluetoothConnected"; name: string; batteryPercent: number | null } | { kind: "bluetoothDisconnected"; name: string } | 
/**
 *  A connected Bluetooth device's battery fell to a threshold (docs/modules/bluetooth.md);
 *  the name is content and is never logged.
 */
{ kind: "deviceBatteryLow"; name: string; percent: number } | { kind: "timerFinished"; label: string } | 
/**
 *  A track change; both fields are content and never logged. The UI lays them out as
 *  title and artist (marquee only when they overflow).
 */
{ kind: "nowPlaying"; title: string; artist: string } | 
/**  The running pomodoro phase ("Focus", "Short break"); the trailing timer counts down. */
{ kind: "pomodoro"; phase: PomodoroPhase } | 
/**  A pomodoro phase ran out (docs/modules/pomodoro.md). */
{ kind: "pomodoroFinished"; phase: PomodoroPhase } | 
/**
 *  A task that is due soon or due now (docs/modules/todo.md); the title is content and is
 *  never logged. As an activity the trailing slot carries the due time; as a notice it
 *  announces the moment.
 */
{ kind: "taskDue"; title: string } | 
/**
 *  A calendar event within the hour or starting now (docs/modules/calendar.md); the title
 *  is content and is never logged. As an activity the trailing slot carries the start
 *  time; as a notice it announces the ten-minute mark.
 */
{ kind: "eventStarting"; title: string } | 
/**
 *  A notification that just arrived, or the latest unread one (docs/modules/
 *  notifications.md); both fields are content and never logged. The UI lays them out as
 *  sender and title.
 */
{ kind: "notification"; app: string; title: string } | 
/**
 *  A drop action working on `count` items (docs/modules/drop-actions.md); the trailing
 *  slot carries its progress. The UI phrases it per action ("Zipping 3 items").
 */
{ kind: "dropRunning"; action: DropActionKind; count: number } | 
/**  A drop action finished; `count` is how many items it handled. */
{ kind: "dropFinished"; action: DropActionKind; count: number } | 
/**  A drop action failed or was cancelled by the user; the reason stays in the log. */
{ kind: "dropFailed"; action: DropActionKind } | 
/**
 *  Someone asked the user to review a pull request (docs/modules/code-hosting.md); the
 *  title is content and is never logged. The UI phrases it ("Review requested · title").
 */
{ kind: "reviewRequested"; title: string } | 
/**
 *  The checks on a pull request the user opened finished (docs/modules/code-hosting.md);
 *  the title is content and is never logged.
 */
{ kind: "checksFinished"; title: string; passed: boolean };

export type SystemMonitorBattery = {
	percent: number,
	charging: boolean,
};

/**
 *  A fresh system reading (docs/modules/system-monitor.md), once a second while a panel
 *  watches. Nothing is emitted while no panel is open.
 */
export type SystemMonitorChanged = {
	snapshot: SystemMonitorSnapshot,
};

/**  One row of the process list: every process sharing an executable name, aggregated. */
export type SystemMonitorProcess = {
	/**  Executable name without its extension; never a window title or a path. */
	name: string,
	/**
	 *  Share of the whole machine in tenths of a percent (123 is 12.3 %), so a quiet process
	 *  still reads as more than zero.
	 */
	cpuTenths: number,
	memoryBytes: number,
	/**  How many processes the row aggregates. */
	count: number,
};

/**
 *  One reading for the panel. Byte counts are saturated to [`Int53`] so a JavaScript
 *  `number` holds them exactly; percentages are whole numbers, as the gauges draw them.
 */
export type SystemMonitorSnapshot = {
	/**  Whole-machine CPU use, 0–100. `None` until two samples exist to difference. */
	cpuPercent: number | null,
	logicalCpus: number,
	memoryUsedBytes: number,
	memoryTotalBytes: number,
	/**  Fixed volumes summed (removable media is not the machine's storage). */
	storageUsedBytes: number,
	storageTotalBytes: number,
	/**  Free space on the system volume — the number that decides whether Windows updates fit. */
	freeDiskBytes: number,
	/**  Capacity of the same volume, so a gauge can draw the free share. */
	systemDiskTotalBytes: number,
	/**  Bytes per second over every hardware interface, `None` until two samples exist. */
	networkDownBytesPerS: number | null,
	networkUpBytesPerS: number | null,
	/**  `None` on a machine without a battery. */
	battery: SystemMonitorBattery | null,
	/**
	 *  The busiest processes, most CPU first; empty while the panel is closed or the setting
	 *  is 0.
	 */
	processes: SystemMonitorProcess[],
	/**  Unix milliseconds of the sample, so a panel can tell a stale reading from a live one. */
	sampledAtMs: number,
};

/**
 *  One task, in any state: open, completed (`completed_at_ms`) or in the trash
 *  (`deleted_at_ms`). The title and notes are content and are never logged.
 */
export type Task = {
	id: string,
	listId: string,
	title: string,
	notes: string,
	dueMs: number | null,
	/**  `due_ms` names a day, not a moment. */
	allDay: boolean,
	completedAtMs: number | null,
	deletedAtMs: number | null,
	/**  Ascending within the list; new tasks go on top. */
	sortOrder: number,
	createdAtMs: number,
	updatedAtMs: number,
};

/**  A due date as the UI sends it. */
export type TaskDue = {
	/**  Unix milliseconds; a JS `number` holds it exactly. */
	atMs: number,
	/**  The date names a day, not a moment; never announced. */
	allDay: boolean,
};

/**
 *  One list of tasks.
 * 
 *  Millisecond and order fields are `i64` in Rust and SQLite and export as `number` through
 *  [`Int53`] (they stay far below 2^53).
 */
export type TaskList = {
	id: string,
	/**  `None` for the default list (localised by the UI). */
	name: string | null,
	sortOrder: number,
};

/**  An accent from the design system (docs/05-design-system.md, colour tokens). */
export type Tint = "blue" | "cyan" | "green" | "orange" | "red" | "purple" | "yellow" | "pink";

/**
 *  The task list changed: a command ran, the trash was purged or a settings change moved the
 *  retention (docs/modules/todo.md). Carries the whole snapshot; a personal list is small.
 */
export type TodoChanged = {
	snapshot: TodoSnapshot,
};

/**
 *  What the panel and the settings pane can ask for. Every command answers with the snapshot
 *  after it; commands naming a task or list that no longer exists are no-ops.
 */
export type TodoCommand = 
/**  A new task at the top of `list_id`. A blank title is refused. */
{ kind: "add"; listId: string; title: string; due: TaskDue | null } | { kind: "rename"; id: string; title: string } | { kind: "setNotes"; id: string; notes: string } | 
/**  `None` clears the due date. */
{ kind: "setDue"; id: string; due: TaskDue | null } | { kind: "complete"; id: string; completed: boolean } | 
/**  To the trash. */
{ kind: "delete"; id: string } | { kind: "restore"; id: string } | 
/**  Out of the trash for good. */
{ kind: "purge"; id: string } | { kind: "emptyTrash" } | 
/**  The named tasks take this order at the top of the list. */
{ kind: "reorder"; listId: string; ids: string[] } | { kind: "addList"; name: string } | { kind: "renameList"; id: string; name: string } | 
/**  The list's tasks move to the default list's trash. */
{ kind: "deleteList"; id: string };

/**
 *  What the panel renders: every list and every task that has not been purged. A personal
 *  list stays small enough to ship whole; the UI filters by list and state.
 */
export type TodoSnapshot = {
	lists: TaskList[],
	tasks: Task[],
	/**  `settings.modules.todo.retentionDays`, so the trash can say when a task goes. */
	retentionDays: number,
};

/**  The trailing (right) slot of the strip. */
export type Trailing = { kind: "icon"; glyph: Glyph; tint: Tint | null } | 
/**  Short text that is already words (a track position, a device name); tabular figures. */
{ kind: "text"; value: string } | 
/**  A percentage the UI formats for the locale. */
{ kind: "percent"; value: number } | 
/**  A battery glyph filled to `percent`, with a bolt while charging. */
{ kind: "battery"; percent: number; charging: boolean } | 
/**
 *  A countdown. The UI ticks it locally from the moment it arrives, so the value need
 *  not be republished every second.
 */
{ kind: "timer"; remainingMs: number; totalMs: number; running: boolean } | 
/**  A 0–100 progress track. */
{ kind: "progress"; percent: number } | 
/**
 *  Audio bars beside album art (docs/modules/media.md, strip form). `playing` animates
 *  them; paused bars rest at a low level.
 */
{ kind: "waveform"; playing: boolean } | 
/**
 *  The HUD's 96 px level track with a white fill (docs/modules/hud.md, "Visual"); the
 *  UI animates the fill between values. `muted` draws the fill dimmed.
 */
{ kind: "level"; percent: number; muted: boolean } | 
/**
 *  A wall-clock instant (Unix milliseconds) the UI formats as a short time for the locale
 *  (a task's due time, an event's start).
 */
{ kind: "time"; atMs: number } | 
/**  A small whole number the UI formats for the locale (unread notifications). */
{ kind: "count"; value: number };

/**
 *  How [`crate::FileOps::transfer`] writes its destination (docs/modules/drop-actions.md,
 *  the *Copy to* / *Move to* and folder tiles).
 */
export type TransferMode = "copy" | "move";

/**  How temperatures and wind speeds read; the forecast itself is always metric. */
export type Units = 
/**  °C and km/h. */
"metric" | 
/**  °F and mph. */
"imperial";

/**  The default render endpoint's level. */
export type VolumeLevel = {
	percent: number,
	muted: boolean,
};

/**
 *  The forecast, its place and the refresh state as the module now sees them
 *  (docs/modules/weather.md): after a fetch, a position fix, a command or a settings change.
 */
export type WeatherChanged = {
	snapshot: WeatherSnapshot,
};

/**
 *  What the panel can ask for. Settings (on/off, units, place) go through the settings
 *  document like every module's.
 */
export type WeatherCommand = 
/**  Fetches now, whatever the schedule says. */
{ kind: "refresh" } | 
/**  Asks Windows for the position again after a denial, an unavailable source or a failure. */
{ kind: "retryLocation" };

/**
 *  A WMO weather interpretation code grouped for an icon, a label and a sky
 *  (Open-Meteo's `weather_code`; docs/modules/weather.md "Visual").
 */
export type WeatherCondition = 
/**  0. */
"clear" | 
/**  1. */
"mainlyClear" | 
/**  2. */
"partlyCloudy" | 
/**  3. */
"overcast" | 
/**  45, 48. */
"fog" | 
/**  51–57. */
"drizzle" | 
/**  61–67. */
"rain" | 
/**  71–77. */
"snow" | 
/**  80–82. */
"showers" | 
/**  85, 86. */
"snowShowers" | 
/**  95–99. */
"thunderstorm" | 
/**  Anything the table does not list. */
"unknown";

/**  What the UI renders (docs/modules/weather.md). */
export type WeatherSnapshot = {
	/**  `false` until the user turns the module on; nothing below is populated meanwhile. */
	enabled: boolean,
	units: Units,
	location: LocationView,
	/**  The last good forecast, possibly from a previous launch or an earlier hour. */
	forecast: Forecast | null,
	/**  When `forecast` was fetched, Unix milliseconds; the timestamp chip while offline. */
	fetchedAtMs: number | null,
	/**  A request is on the wire. */
	fetching: boolean,
	/**
	 *  Why the last refresh failed; cleared by the next one that works. The forecast, if any,
	 *  stays.
	 */
	error: FetchError | null,
};

/**  What one notch window does about the world around it. */
export type YieldState = 
/**  Nothing in the way. */
"none" | 
/**  A title bar or a window drag is under the strip: the UI slides the strip up to 6 px. */
"peek" | 
/**  Fullscreen, locked or paused: the window is moved above the monitor and the UI pauses. */
"parked";

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

